arguments.command:
curl -s -X POST https://slack.com/api/conversations.list -H "Content-Type: application/json" -d '{"token":"***","types":"public_channel,private_channel","exclude_archived":true}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print('ERR',d); sys.exit()
for c in d['channels']:
    if 'incident' in c['name'].lower():
        print(c['id'], c['name'])
"

